from collections import deque

def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str):
        return None
    if not path.startswith('/'):
        if not cwd.startswith('/'):
            return None
        path = cwd.rstrip('/') + '/' + path
        if path == '':
            path = '/'
    tokens = deque(path.split('/'))
    result = []  # resolved path segments, without leading slash, in order
    link_count = 0

    while tokens:
        comp = tokens.popleft()
        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            if result:
                result.pop()
            # '..' at root stays at root
        else:
            candidate = '/' + '/'.join(result + [comp])
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[candidate]
                if not isinstance(target, str):
                    return None
                if target.startswith('/'):
                    new_tokens = target.split('/')
                else:
                    dir_path = '/' + '/'.join(result)
                    combined = dir_path.rstrip('/') + '/' + target
                    if combined == '':
                        combined = '/'
                    new_tokens = combined.split('/')
                # prepend new tokens to remaining tokens
                tokens = deque(new_tokens) + tokens
            else:
                result.append(comp)

    if not result:
        return '/'
    return '/' + '/'.join(result)

